#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int rule110(int left, int center, int right) {
    int result = (left << 2) | (center << 1) | right;
    return (result >> 3) & 1;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("INVALID_INPUT\n");
        return 1;
    }
    int generations = atoi(argv[2]);
    if (generations < 0) {
        printf("INVALID_INPUT\n");
        return 1;
    }
    int size = strlen(argv[1]);
    char *row = (char *)malloc(size + 1);
    strcpy(row, argv[1]);
    for (int i = 0; i < generations; i++) {
        char *new_row = (char *)malloc(size + 1);
        for (int j = 0; j < size; j++) {
            int left = (j == 0) ? 0 : row[j - 1] - '0';
            int center = row[j] - '0';
            int right = (j == size - 1) ? 0 : row[j + 1] - '0';
            new_row[j] = '0' + rule110(left, center, right);
        }
        new_row[size] = '\0';
        printf("%s\n", new_row);
        free(row);
        row = new_row;
    }
    free(row);
    return 0;
}
